const chatCities=[...$('#city').options].map(o=>o.value);
const chatAliases={residence:['居住证','暂住证','居住登记'],social:['社保卡','医保卡','社会保障卡'],fund:['公积金','租房提取','购房提取'],medical:['异地就医','异地医保','跨省看病','异地看病','外地看病','医保备案'],id:['身份证','身份证件'],pension:['养老保险','社保转移','养老转移','养老关系']};
const chatScenarios=['首次办理 / 常规申请','补领 / 换领','异地办理','为家人代办'];
const scenarioHelp={'首次办理 / 常规申请':'先确认申请资格及首次申请所需信息。','补领 / 换领':'补领、损坏换领和到期换领的材料可能不同，请先核实原证件、挂失及核验要求。','异地办理':'先确认户籍地或参保地与办理地是否一致，以及是否支持异地受理。','为家人代办':'先确认是否允许代办，再核实委托书和双方身份证明要求。'};
let chatState={city:'',id:'',scenario:'',step:'service'};let chatHistory=[];
function parseNeed(text){const found=services.filter(s=>chatAliases[s.id].some(a=>text.includes(a))).map(s=>s.id);const cities=chatCities.filter(c=>text.includes(c.replace(/市$/,'')));let scenario='';if(/代办|家人|父母|爸爸|妈妈|帮(?:亲人|朋友|父亲|母亲).*办/.test(text))scenario=chatScenarios[3];else if(/补办|补领|丢失|丢了|换领|换证|到期|遗失/.test(text))scenario=chatScenarios[1];else if(/异地办理|异地办|跨市办理|跨省办理/.test(text))scenario=chatScenarios[2];else if(/首次|第一次|常规/.test(text))scenario=chatScenarios[0];return {ids:found,cities,scenario}}
function addChat(role,text){chatHistory.push({role,text});const row=document.createElement('div');row.className='chat-message '+role;const icon=document.createElement('span');icon.className='chat-avatar';icon.textContent=role==='assistant'?'✧':'你';const body=document.createElement('div');body.className='chat-bubble';body.textContent=text;row.append(icon,body);$('#chatMessages').append(row);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight}
function chooseChats(choices){$('#chatSuggestions').replaceChildren();choices.forEach(c=>{const b=document.createElement('button');b.type='button';b.textContent=typeof c==='string'?c:c.label;b.onclick=()=>{if(typeof c!=='string'&&c.action){c.action();return}submitChat(typeof c==='string'?c:c.value)};$('#chatSuggestions').append(b)})}
function renderChatSummary(){const s=services.find(s=>s.id===chatState.id);$('#chatSummary').replaceChildren();[['办理城市',chatState.city||'待补充'],['办事事项',s?s.name:'待补充'],['办理情形',chatState.scenario||'待补充']].forEach(([label,value])=>{const d=document.createElement('div');d.className='context-item';const l=document.createElement('small');l.textContent=label;const v=document.createElement('b');v.textContent=value;d.append(l,v);$('#chatSummary').append(d)})}
function offerRoute(){chooseChats([{label:'生成我的办事路线 →',action:()=>{openRoute(chatState.id);active.city=chatState.city;active.scenario=chatState.scenario;$('#routeTitle').textContent=chatState.city+' · '+services.find(s=>s.id===chatState.id).name;$('#scenario').value=chatState.scenario;$('#scenario').dispatchEvent(new Event('change'));}},{label:'还有哪些材料？',value:'需要哪些材料'},{label:'可以线上办吗？',value:'可以线上办吗'},{label:'重新开始',action:resetChat}])}
function advanceChat(){renderChatSummary();if(!chatState.id){chatState.step='service';addChat('assistant','你想办理哪件事？目前支持下方 6 类事项。可以直接选，也可以用自己的话描述。');chooseChats(services.map(s=>s.name));return}if(!chatState.city){chatState.step='city';addChat('assistant','了解，你要办理「'+services.find(s=>s.id===chatState.id).name+'」。准备在哪个城市办理？');chooseChats(chatCities);return}if(!chatState.scenario){chatState.step='scenario';addChat('assistant','已记下：'+chatState.city+' · '+services.find(s=>s.id===chatState.id).name+'。这次属于哪种办理情形？如果同时符合多种情形，先选最主要的一种。');chooseChats(chatScenarios);return}chatState.step='ready';const s=services.find(s=>s.id===chatState.id);addChat('assistant','已整理你的需求：\n办理城市：'+chatState.city+'\n办事事项：'+s.name+'\n办理情形：'+chatState.scenario+'\n\n'+scenarioHelp[chatState.scenario]+'\n\n接下来可以生成路线、逐项核对材料，并保存到「我的办事」。清单是演示规划，具体要求仍需以当地官方指南为准。');offerRoute()}
function submitChat(raw){const text=raw.trim();if(!text)return;$('#chatInput').value='';addChat('user',text);if(/^(重新开始|重来|清空)$/.test(text)){resetChat();return}const p=parseNeed(text);if(!p.cities.length&&/(?:我在|城市是|改到|换到|办理城市是)/.test(text)){chatState.city='';renderChatSummary();addChat('assistant','暂未识别到支持的办理城市。目前支持上海、北京、深圳、杭州、广州、成都，请选择实际办理城市。');chooseChats(chatCities);return}if(p.ids.length>1){addChat('assistant','你提到了多个事项，我们先办一件，避免混淆材料。请先选本次要规划的事项。');chooseChats(p.ids.map(id=>services.find(s=>s.id===id).name));return}if(p.cities.length>1){addChat('assistant','你提到了多个城市。这里记录的是办理城市，请选择本次准备办理的城市；涉及跨地政策时，还需确认参保地或户籍地要求。');chooseChats(p.cities);return}if(p.ids.length===1&&p.ids[0]!==chatState.id){chatState.id=p.ids[0];chatState.scenario=''}if(p.cities.length===1)chatState.city=p.cities[0];if(p.scenario)chatState.scenario=p.scenario;if(chatScenarios.includes(text))chatState.scenario=text;renderChatSummary();const s=services.find(s=>s.id===chatState.id);
if(/照片|相片|尺寸|底色/.test(text)){addChat('assistant','不同城市和事项的照片尺寸、底色、回执及采集方式可能不同。目前还没有经过核验的规格库。请在官方指南中确认：是否需近期照片、电子版或纸质版、指定尺寸和底色，以及是否需要照片回执。不要把证件照片上传到本站。');chooseChats([{label:'继续规划',action:advanceChat}]);return}
if(/费用|多少钱|收费|时限|多久|地址|窗口在哪|邮寄|线上|线下|预约|能不能|可以.*办/.test(text)){addChat('assistant','这类要求需要按城市、事项和办理情形核实。目前本站未连接实时政务系统，不能确认是否可全程网办、费用、受理时限或窗口地址。\n\n建议通过当地官方政务服务平台检索事项全称，核对申请条件、办理形式、预约要求、邮寄或代办条件。路线中提供官方门户参考入口。');chooseChats([{label:'继续整理需求',action:advanceChat}]);return}
if(/材料|带什么|准备什么|复印/.test(text)&&s){addChat('assistant','「'+s.name+'」的演示准备方向：\n'+s.materials.map((m,i)=>(i+1)+'. '+m[0]+'：'+m[1]).join('\n')+'\n\n这不是完整的官方受理清单。生成路线后可以勾选自查；复印件数量、原件要求需向受理部门确认。');if(chatState.step==='ready')offerRoute();else chooseChats([{label:'继续补充情况',action:advanceChat}]);return}
if(!p.ids.length&&!p.cities.length&&!p.scenario&&!chatScenarios.includes(text)&&!chatState.id){addChat('assistant','我暂时没有识别到支持的办事事项。你可以说“想办居住证”或“医保卡丢了要补办”，也可以从下方选择。目前是规则式需求引导，不提供政策判断或任意问题解答。');chooseChats(services.map(s=>s.name));return}
if(chatState.step==='city'&&!p.cities.length){addChat('assistant','首版支持上海、北京、深圳、杭州、广州、成都。其他城市暂未开放，请选择实际办理城市；不要为了继续而选不相关的城市。');chooseChats(chatCities);return}
if(chatState.step==='scenario'&&!p.scenario&&!chatScenarios.includes(text)&&!p.ids.length&&!p.cities.length){addChat('assistant','为了给你合适的准备提示，请选择最贴近的办理情形。');chooseChats(chatScenarios);return}advanceChat()}
function resetChat(){chatState={city:'',id:'',scenario:'',step:'service'};chatHistory=[];$('#chatMessages').replaceChildren();addChat('assistant','你好，我是办事小助手。\n你可以告诉我“在哪个城市，想办理什么”，我会一步步帮你整理需求。\n\n例如：我在上海，社保卡丢了，想补办。');chooseChats(['我在上海，想申领居住证','我的社保卡丢了，想补办','想了解异地就医备案']);renderChatSummary()}
const originalGo=go;go=function(v){$('#chatView').hidden=v!=='chat';if(v==='chat'){view=v;$('#homeView').hidden=true;$('#otherView').hidden=true;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#pageName').textContent='语音对话助手';window.scrollTo({top:0,behavior:'smooth'});return}originalGo(v)};
$$('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#heroChat').onclick=()=>go('chat');$('#resetChat').onclick=resetChat;$('#chatForm').onsubmit=e=>{e.preventDefault();submitChat($('#chatInput').value)};$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submitChat($('#chatInput').value)}};resetChat();
// Saved route updates must also work while the conversation view is active.
const originalRenderOther=renderOther;renderOther=function(){if(view==='chat'||view==='home')return;originalRenderOther()};
